INSERT INTO feature VALUES('migrate-wire','runtime','A migration shipped to the process its world is bound to','world-migration','partial','unique','mainstream languages','A host''s world bindings, `--world <world>=<key>@<ip:port>` or the manifold they desugar from, bind each declared world to the key of the process it runs at: `gandr run` ships a migration to a world bound to another key over the world wire — its code named by the program''s digest and its place, each capture by its manifest — and `gandr host` of the same source runs it, fetching over the migration''s connection only the captures it does not hold whole, and the answer crosses back by content. The far host answers the body''s operations with its own handler, attenuated to the world''s row, and nothing of the caller''s host crosses (#3546). A migration to a world bound to this host runs here, and an entry that may migrate to a world no binding names is refused `UnboundWorld` before it runs. Both processes hold the program as source; a far host loading it by content key is owed (#3293).','runtime-net runtime-emitter surface-dispatcher surface-evaluate surface-driver','corpus/ledger/features/migrate-wire.gandr corpus/model/worlds/two-processes.gandr corpus/model/worlds/two-processes.manifold.gandr crates/runtime-net/tests/worlds.rs crates/runtime-emitter/tests/world.rs crates/surface-dispatcher/tests/run.rs crates/surface-driver/tests/net.rs','corpus/ledger/features/migrate-wire.gandr','#3293');
